#include "termio/Output.hpp"
#include "termio/Csi.hpp"
#include "termio/Dec.hpp"
#include "termio/OscLink.hpp"
#include <iostream>
using namespace batbox;using namespace batbox::termio;
Json constants(){return Json{{"CSI_PREFIX",CSI_PREFIX},{"CURSOR_LEFT",CURSOR_LEFT},{"CURSOR_HOME",CURSOR_HOME},{"CURSOR_SAVE",CURSOR_SAVE},{"CURSOR_RESTORE",CURSOR_RESTORE},{"ERASE_LINE",ERASE_LINE},{"ERASE_SCREEN",ERASE_SCREEN},{"ERASE_SCROLLBACK",ERASE_SCROLLBACK},{"RESET_SCROLL_REGION",RESET_SCROLL_REGION},{"PASTE_START",PASTE_START},{"PASTE_END",PASTE_END},{"FOCUS_IN",FOCUS_IN},{"FOCUS_OUT",FOCUS_OUT},{"ENABLE_KITTY_KEYBOARD",ENABLE_KITTY_KEYBOARD},{"DISABLE_KITTY_KEYBOARD",DISABLE_KITTY_KEYBOARD},{"ENABLE_MODIFY_OTHER_KEYS",ENABLE_MODIFY_OTHER_KEYS},{"DISABLE_MODIFY_OTHER_KEYS",DISABLE_MODIFY_OTHER_KEYS},{"BSU",BSU},{"ESU",ESU},{"EBP",EBP},{"DBP",DBP},{"EFE",EFE},{"DFE",DFE},{"SHOW_CURSOR",SHOW_CURSOR},{"HIDE_CURSOR",HIDE_CURSOR},{"ENTER_ALT_SCREEN",ENTER_ALT_SCREEN},{"EXIT_ALT_SCREEN",EXIT_ALT_SCREEN},{"ENABLE_MOUSE_TRACKING",ENABLE_MOUSE_TRACKING},{"DISABLE_MOUSE_TRACKING",DISABLE_MOUSE_TRACKING}};}
int main(){Json cases;std::cin>>cases;Json all=Json::array();for(const auto& item:cases){Json calls=Json::array(),writes=Json::array(),results=Json::array(),env=item.value("env",Json::object());std::string terminal=item.value("terminal","");TerminalEnvironment context{item.value("platform","linux"),[&](const std::string& key)->std::optional<std::string>{calls.push_back(key);if(!env.contains(key)||env[key].is_null())return {};return env[key].get<std::string>();}};
 ClearModule clear(context);OscModule oscModule([&]{return terminal;});auto services=indigenousOutputServices(context,[&]{return terminal;});calls=Json::array();
 for(const auto& op:item.at("steps")){Json value=nullptr;const auto kind=op.at("op").get<std::string>();const auto args=op.value("args",Json::array());const auto n=[&](std::size_t i,double fallback=1.0){return i<args.size()?args[i].get<double>():fallback;};const auto name=op.value("name","");
 if(kind=="constant"){if(name=="clearTerminal")value=clear.clearTerminal();else if(name=="LINK_END")value=oscModule.linkEnd();else value=constants().at(name);}
 else if(kind=="terminal")terminal=op.at("value").get<std::string>();else if(kind=="setenv")env[op.at("key").get<std::string>()]=op.at("value");
 else if(kind=="diff")writeDiffToTerminal([&](const std::string& text){writes.push_back(text);},op.at("diff"),op.value("skip",false),services);
 else if(name=="csi")value=csi(args);else if(name=="cursorUp")value=cursorUp(n(0));else if(name=="cursorDown")value=cursorDown(n(0));else if(name=="cursorForward")value=cursorForward(n(0));else if(name=="cursorBack")value=cursorBack(n(0));else if(name=="cursorTo")value=cursorTo(n(0));else if(name=="cursorPosition")value=cursorPosition(n(0),n(1));else if(name=="cursorMove")value=cursorMove(n(0),n(1));
 else if(name=="eraseToEndOfLine")value=eraseToEndOfLine();else if(name=="eraseToStartOfLine")value=eraseToStartOfLine();else if(name=="eraseLine")value=eraseLine();else if(name=="eraseToEndOfScreen")value=eraseToEndOfScreen();else if(name=="eraseToStartOfScreen")value=eraseToStartOfScreen();else if(name=="eraseScreen")value=eraseScreen();else if(name=="eraseLines")value=eraseLines(n(0));else if(name=="scrollUp")value=scrollUp(n(0));else if(name=="scrollDown")value=scrollDown(n(0));else if(name=="setScrollRegion")value=setScrollRegion(n(0),n(1));
 else if(name=="decset")value=decset(n(0));else if(name=="decreset")value=decreset(n(0));else if(name=="isCSIParam")value=isCSIParam(n(0));else if(name=="isCSIIntermediate")value=isCSIIntermediate(n(0));else if(name=="isCSIFinal")value=isCSIFinal(n(0));
 else if(name=="getClearTerminalSequence")value=clear.getClearTerminalSequence();else if(name=="isWindowsTerminal")value=isWindowsTerminal(context);else if(name=="isMintty")value=isMintty(context);else if(name=="isModernWindowsTerminal")value=isModernWindowsTerminal(context);
 else if(name=="osc8Id")value=osc8Id(args.at(0));else if(name=="osc")value=osc(args,terminal);else if(name=="link")value=oscModule.link(args.at(0),args.size()>1?std::optional<Json>(args.at(1)):std::nullopt);
 else throw std::runtime_error("Unknown terminal fixture function "+name);
 results.push_back(value);
 }all.push_back(Json{{"results",results},{"writes",writes},{"calls",calls}});}std::cout<<value::stringify(all)<<'\n';}
